Write-Host "Created public/icon-192.png" -ForegroundColor Green
$b64_icon_512 = ""
[IO.File]::WriteAllBytes("public/icon-512.png", [Convert]::FromBase64String($b64_icon_512))
Write-Host "Created public/icon-512.png" -ForegroundColor Green
dir public\icon*.png
$b64_favicon = ""
[IO.File]::WriteAllBytes("public/favicon.ico", [Convert]::FromBase64String($b64_favicon))
Write-Host "Created public/favicon.ico" -ForegroundColor Green
dir public\icon*.png; dir public\favicon.ico
git add -f public/icon-192.png public/icon-512.png public/favicon.ico
git commit -m "Fix icons real PNGs"
git push origin main
